import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally opponent behavior
    opp_defects = 0
    for _, o in history:
        if o == 'D':
            opp_defects += 1
    rate = opp_defects / n

    last_me, last_opp = history[-1]

    # Count current opponent defection streak
    tail_def = 0
    for _, o in reversed(history):
        if o == 'D':
            tail_def += 1
        else:
            break

    # Late-game exploitation window
    remaining = 100 - n

    # Very short match start
    if n == 1:
        return 'D' if last_opp == 'D' else 'C'
    if n == 2:
        if opp_defects == 0:
            return 'C'
        return 'D'

    # Opponent extremely cooperative: exploit near end, mostly reciprocate otherwise
    if opp_defects == 0:
        if remaining <= 3:
            return 'D'
        # occasional cheap shot when they've shown they won't retaliate
        if n >= 12 and n % 11 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent extremely defective: punish hard, but probe occasionally
    if rate > 0.85:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_opp == 'D':
        if tail_def >= 3:
            return 'D'
        if rate > 0.35:
            return 'D'
        # A retaliatory defection, but forgive quickly against nice opponents
        if rate < 0.15 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated
    if rate > 0.5:
        # Moderately untrustworthy: exploit more aggressively
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if rate > 0.25:
        # Mixed opponent: reciprocate, with occasional opportunism
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    # Mostly cooperative opponent
    if last_me == 'D':
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # End-game defection against cooperative opponents
    if remaining <= 2:
        return 'D'
    if remaining <= 4 and rate < 0.2:
        if rng.random() < 0.5:
            return 'D'

    # Optional probe against very nice opponents
    if rate < 0.12 and n >= 8 and n % 13 == 0 and rng.random() < 0.25:
        return 'D'

    return 'C'
